using System;using System.IO;using System.Linq;using System.Net;using System.Net.Http;using System.Security.Cryptography;using System.Text;using System.Threading;using System.Threading.Tasks;using System.Web.Script.Serialization;using System.Xml.Serialization;
public sealed class LibraryOptions {
 public string Address="http://127.0.0.1:34827",ProtectedKey="";
 internal static string ConfigPath {get{return Path.Combine(Preferences.Folder,"library-client.xml");}}
 internal string Key {get{try{return Encoding.UTF8.GetString(ProtectedData.Unprotect(Convert.FromBase64String(ProtectedKey),null,DataProtectionScope.CurrentUser));}catch{return "";}}set{ProtectedKey=Convert.ToBase64String(ProtectedData.Protect(Encoding.UTF8.GetBytes(value),null,DataProtectionScope.CurrentUser));}}
 internal static LibraryOptions Load(){try{using(var file=File.OpenRead(ConfigPath))return (LibraryOptions)new XmlSerializer(typeof(LibraryOptions)).Deserialize(file);}catch{return new LibraryOptions();}}
 internal void Save(){Directory.CreateDirectory(Preferences.Folder);string temp=ConfigPath+".tmp";using(var file=File.Create(temp))new XmlSerializer(typeof(LibraryOptions)).Serialize(file,this);if(File.Exists(ConfigPath))File.Replace(temp,ConfigPath,null);else File.Move(temp,ConfigPath);}
}
internal sealed class LibraryFailure : Exception {internal int Code;internal LibraryFailure(int code,string message):base(message){Code=code;}}
internal sealed class LibraryClient : IDisposable {
 readonly HttpClient http;readonly Uri baseUri;readonly string key;internal readonly string Cache;readonly JavaScriptSerializer json=new JavaScriptSerializer{MaxJsonLength=262144};
 internal LibraryClient(string address,string password,string cache=null){Uri uri;if(!Uri.TryCreate(address.Trim().TrimEnd('/')+"/",UriKind.Absolute,out uri)||(uri.Scheme!="http"&&uri.Scheme!="https")||!String.IsNullOrEmpty(uri.UserInfo)||uri.AbsolutePath!="/"||!String.IsNullOrEmpty(uri.Query)||!String.IsNullOrEmpty(uri.Fragment))throw new ArgumentException("請輸入 http://主機位址:連接埠");baseUri=uri;key=Convert.ToBase64String(Encoding.UTF8.GetBytes(password??""));Cache=cache??Path.Combine(Preferences.Folder,"Downloads");Directory.CreateDirectory(Cache);http=new HttpClient(new HttpClientHandler{UseProxy=false,AllowAutoRedirect=false,UseDefaultCredentials=false}){Timeout=Timeout.InfiniteTimeSpan};}
 internal async Task Ping(CancellationToken token){using(var timeout=CancellationTokenSource.CreateLinkedTokenSource(token)){timeout.CancelAfter(3000);using(var response=await Send(HttpMethod.Get,"health",null,timeout.Token)){} }}
 internal async Task<AssetPage> List(int page,CancellationToken token){using(var timeout=CancellationTokenSource.CreateLinkedTokenSource(token)){timeout.CancelAfter(4000);using(var response=await Send(HttpMethod.Get,"assets?page="+Math.Max(0,page),null,timeout.Token)){string text=Encoding.UTF8.GetString(await ReadLimited(await response.Content.ReadAsStreamAsync(),262144,timeout.Token));var result=json.Deserialize<AssetPage>(text);if(result==null||result.Items==null||result.Items.Length>12||result.Total<0)throw new InvalidDataException("素材清單格式不正確");foreach(var item in result.Items)Validate(item);return result;}}}
 internal async Task<AssetInfo> Upload(string path,CancellationToken token){var info=new FileInfo(path);if(info.Length<1||info.Length>LibraryStore.MaxBytes)throw new InvalidDataException("素材上限為 20 MB。");using(var timeout=CancellationTokenSource.CreateLinkedTokenSource(token)){timeout.CancelAfter(120000);using(var file=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read,32768,true))using(var content=new StreamContent(file,32768))using(var request=new HttpRequestMessage(HttpMethod.Post,new Uri(baseUri,"assets"))){content.Headers.ContentLength=info.Length;request.Content=content;request.Headers.ExpectContinue=false;request.Headers.Add("X-Library-Key",key);request.Headers.Add("X-File-Name",Uri.EscapeDataString(info.Name));using(var response=await http.SendAsync(request,HttpCompletionOption.ResponseHeadersRead,timeout.Token)){await Check(response);var item=json.Deserialize<AssetInfo>(Encoding.UTF8.GetString(await ReadLimited(await response.Content.ReadAsStreamAsync(),65536,timeout.Token)));Validate(item);return item;}}}}
 internal async Task<string> Download(AssetInfo item,CancellationToken token){Validate(item);string destination=Path.Combine(Cache,item.Id+item.Extension);if(File.Exists(destination)&&new FileInfo(destination).Length==item.Bytes&&LibraryStore.Hash(destination)==item.Id){Record(item);return destination;}string part=Path.Combine(Cache,Guid.NewGuid().ToString("N")+".part");try{
  using(var timeout=CancellationTokenSource.CreateLinkedTokenSource(token)){timeout.CancelAfter(120000);using(var response=await Send(HttpMethod.Get,"files/"+item.Id,null,timeout.Token))using(var input=await response.Content.ReadAsStreamAsync())using(var output=new FileStream(part,FileMode.CreateNew,FileAccess.Write,FileShare.None,32768,true)){await CopyLimited(input,output,item.Bytes,timeout.Token);}}
  if(new FileInfo(part).Length!=item.Bytes||LibraryStore.Hash(part)!=item.Id)throw new InvalidDataException("下載檔案驗證失敗，請重試。");using(var image=System.Drawing.Image.FromFile(part)){if(image.Width!=item.Width||image.Height!=item.Height)throw new InvalidDataException("下載圖片尺寸不符。");}
  if(File.Exists(destination))File.Delete(destination);File.Move(part,destination);Record(item);return destination;
 }finally{if(File.Exists(part))File.Delete(part);}}
 internal async Task<byte[]> Thumbnail(AssetInfo item,CancellationToken token){Validate(item);string path=Path.Combine(Cache,item.Id+".thumb.png");if(File.Exists(path)&&new FileInfo(path).Length<=262144)return File.ReadAllBytes(path);using(var timeout=CancellationTokenSource.CreateLinkedTokenSource(token)){timeout.CancelAfter(4000);using(var response=await Send(HttpMethod.Get,"thumbs/"+item.Id,null,timeout.Token)){byte[] bytes=await ReadLimited(await response.Content.ReadAsStreamAsync(),262144,timeout.Token);using(var ms=new MemoryStream(bytes))using(var image=System.Drawing.Image.FromStream(ms)){if(image.Width>160||image.Height>120)throw new InvalidDataException("縮圖尺寸不正確");}File.WriteAllBytes(path,bytes);return bytes;}}}
 void Record(AssetInfo item){string path=Path.Combine(Cache,item.Id+".json"),temp=path+".tmp";File.WriteAllText(temp,json.Serialize(item));if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}
 internal static AssetInfo[] LocalPage(string cache,int page,out int total){Directory.CreateDirectory(cache);var files=new DirectoryInfo(cache).EnumerateFiles("*.json").OrderByDescending(f=>f.LastWriteTimeUtc).ToArray();total=files.Length;var list=new System.Collections.Generic.List<AssetInfo>();foreach(var file in files.Skip(Math.Max(0,page)*12).Take(12))try{if(file.Length>65536)continue;var item=new JavaScriptSerializer().Deserialize<AssetInfo>(File.ReadAllText(file.FullName));Validate(item);if(File.Exists(Path.Combine(cache,item.Id+item.Extension)))list.Add(item);}catch{}return list.ToArray();}
 static void Validate(AssetInfo item){if(item==null||!LibraryStore.ValidId(item.Id)||!new[]{".gif",".png",".jpg",".bmp"}.Contains(item.Extension)||item.Bytes<1||item.Bytes>LibraryStore.MaxBytes||item.Width<1||item.Height<1||item.Width>4096||item.Height>4096||item.Name==null||item.Name.Length>120)throw new InvalidDataException("素材資訊不正確");}
 async Task<HttpResponseMessage> Send(HttpMethod method,string path,HttpContent content,CancellationToken token){using(var request=new HttpRequestMessage(method,new Uri(baseUri,path))){request.Headers.Add("X-Library-Key",key);request.Content=content;var response=await http.SendAsync(request,HttpCompletionOption.ResponseHeadersRead,token);try{await Check(response);return response;}catch{response.Dispose();throw;}}}
 static Task Check(HttpResponseMessage response){if(response.IsSuccessStatusCode)return Task.FromResult(0);int code=(int)response.StatusCode;throw new LibraryFailure(code,code==401?"共享密碼不正確":code==413?"素材上限為 20 MB":code==415?"素材格式無效或動畫過大":code==404?"素材不存在，請重新整理":"主機回應錯誤（"+code+"）");}
 static async Task<byte[]> ReadLimited(Stream input,int maximum,CancellationToken token){using(input)using(var output=new MemoryStream()){await CopyLimited(input,output,maximum,token);return output.ToArray();}}
 static async Task CopyLimited(Stream input,Stream output,long maximum,CancellationToken token){var buffer=new byte[32768];long total=0;int n;while((n=await input.ReadAsync(buffer,0,buffer.Length,token))>0){total+=n;if(total>maximum)throw new InvalidDataException("傳輸大小超過限制");await output.WriteAsync(buffer,0,n,token);}}
 public void Dispose(){http.Dispose();}
}
